from django.core.management.base import BaseCommand
from common.models import FormFieldSetting

class Command(BaseCommand):
    help='Initialize editable General Ledger wording without creating journal entries.'
    def handle(self,*args,**kwargs):
        ui={'all_units':'All units','single_unit_label':'1','unit_selection_conflict':'Choose All or individual unit options, not both.','unit_search':'Search units…','matches':'matching journal lines','prior_balance':'Prior balance','account_total':'Total','property_level':'Property level','amount':'Amount','description':'Description','account_select':'Select…','account_multiple':'Multiple','account_all':'All accounts','account_search':'Search accounts…','all_properties':'All','properties':'Properties','posted_account_type':'The accounting type cannot change after journal entries have been posted to this account.','title':'General ledger','new':'Record journal entry','all_scope':'All properties and company','property_scope':'Selected property','scope':'Scope','property':'Property','unit':'Unit','accounts':'Accounts','account':'Account','company':'Company','date_range':'Date range','month':'This month','year':'This year','last30':'Last 30 days','custom':'Custom dates','start':'From','end':'To','fund_type':'Fund type','all_funds':'All fund types','unknown':'Unknown / not assigned','search':'Search','reset':'Reset','export':'Export CSV','date':'Date','memo':'Memo / reason','journal':'Journal','debit':'Debit','credit':'Credit','balance':'Balance','opening':'Opening balance','closing':'Closing balance','total':'Period totals','post':'Post balanced journal','cancel':'Cancel','add_line':'Add line','lines':'Journal lines','reverse':'Reverse journal','confirm_reverse':'Post reversal','back':'Back to General ledger','posted_by':'Posted by','basis':'Accrual · posted journals','empty':'No posted journal entries match these filters.','coverage':'This ledger reports balanced journal entries posted in COL360. Existing rent charges, rent receipts, vendor bills, vendor payments and bank setup balances are not automatically posted here. No opening balances are inferred.','report_help':'Balances use the normal side of each account: debit for assets and expenses, credit for liabilities, equity and income. Opening balances include posted journal lines before the selected period. Selected-account totals may differ because other sides of a journal are excluded by the filter.','entry_help':'Post only verified accounting entries. Debits must equal credits, with at least two lines. A blank property records a company-level entry. Journal fund type must match accounts with an assigned fund type. Posted entries cannot be edited or deleted; use a dated reversal for corrections. Posting here does not collect money, pay a vendor, or change the rent subledger.','reverse_help':'This creates equal and opposite journal lines. It does not delete the original or refund money. Enter the correction reason.','immutable':'Posted journals are read-only. Create a reversal to correct an entry.','memo_required':'Enter a memo or correction reason.','balanced':'Enter at least two lines with equal, positive total debits and credits.','line_invalid':'Each line needs a positive debit OR credit, with no more than two decimal places.','inactive_account':'Select active chart accounts for new entries.','unit_mismatch':'Select a unit belonging to the selected property.','invalid_fund':'Choose a configured fund type.','fund_mismatch':'Journal fund type must match each account with an assigned fund type.','date_order':'To date must be on or after From date.','property_required':'Choose a property for this scope.','future':'Journal dates cannot be in the future.','already_reversed':'This journal cannot be reversed again. Review its linked correction.','reversal_date':'Reversal date must be on or after the original journal date.','expired':'This form expired. Reload it before posting.','retry':'This submission could not be posted. Review the journal list before trying again.','reverses':'Reverses journal','reversed_by':'Reversed by journal','posted':'Posted','max_lines':'Maximum 50 lines per journal.'}
        ledger,_=FormFieldSetting.objects.get_or_create(form_key='general_ledger',field_key='ui',defaults={'label':'General ledger interface','option_labels':ui})
        labels=dict(ledger.option_labels)
        for key in ('properties','all_properties','account_select','account_multiple','account_all','account_search','matches','prior_balance','account_total','property_level','amount','description','unit_selection_conflict','unit_search','all_units','single_unit_label'):labels.setdefault(key,ui[key])
        if labels!=ledger.option_labels:
            ledger.option_labels=labels;ledger.save(update_fields=['option_labels'])
        row=FormFieldSetting.objects.get(form_key='accounting_workspace',field_key='ui')
        options=dict(row.option_labels);options.setdefault('rent','Rent ledger')
        if options!=row.option_labels:row.option_labels=options;row.save(update_fields=['option_labels'])
        self.stdout.write(self.style.SUCCESS('General Ledger settings initialized. No journals or balances were created.'))
